values ('bacc2020-2014-4200-8000-000000000001', 'អត្ថបទគំរូ (AI)៖ ការធ្វើបន្តិចម្តងៗ តែជាប់លាប់ (រៀន សន្សំ ធ្វើការ) ទីបំផុតនឹងបានលទ្ធផលធំ ដូចទឹកស្រក់តក់ៗ ដែលពេញបំពង់។ ឧទាហរណ៍៖ កុលាបប៉ៃលិន សូផាត រាមកេរ្តិ៍ (និងច្បាប់ក្រមង៉ុយ)។ ចុច «Show the working» ដើម្បីអានទាំងស្រុង។', null, null, null, '[{"content":"ទម្រង់៖ សេចក្តីផ្តើម (លំនាំ ចំណូល ចំណោទបញ្ហា) · តួសេចក្តី (ពន្យល់ពាក្យ ពន្យល់ន័យ បំណកស្រាយ ឧទាហរណ៍បីរឿង សរុបមតិ) · សេចក្តីបញ្ចប់ (វាយតម្លៃ និងមតិផ្ទាល់ខ្លួន)។"},{"content":"សេចក្តីផ្តើម៖ មនុស្សជាច្រើនចង់បានលទ្ធផលធំភ្លាមៗ តែពិតប្រាកដ ជោគជ័យកើតពីការប្រមូលបន្តិចម្តងៗ។ ហេតុនេះមានសុភាសិតខ្មែរថា «តក់ៗពេញបំពង់»។ តើសុភាសិតនេះមានន័យដូចម្តេច?"},{"content":"ពន្យល់ពាក្យ និងន័យ៖ តក់ៗ គឺទឹកស្រក់ម្តងមួយដំណក់ៗ។ បំពង់ គឺបំពង់ឫស្សីសម្រាប់ដាក់ទឹក។ ពេញបំពង់ គឺទឹកឡើងពេញ។ សុភាសិតនេះមានន័យថា ការធ្វើអ្វីមួយបន្តិចៗ តែធ្វើជាប្រចាំ និងអត់ធ្មត់ ទីបំផុតនឹងបានលទ្ធផលធំ។"},{"content":"បំណកស្រាយ៖ សុភាសិតនេះអនុវត្តលើគ្រប់ផ្នែក៖ ការសិក្សា (រៀនមួយមេរៀនៗ ក្លាយជាចំណេះច្រើន) ការសន្សំ (សន្សំលុយបន្តិចៗ ក្លាយជាទុនធំ) ការងារ និងការកសាងចរិតល្អ។ វាបង្រៀនឲ្យមានការអត់ធ្មត់ ជាប់លាប់ មិនខ្ជះខ្ជាយ មិនមើលងាយរឿងតូច។"},{"content":"ឧទាហរណ៍ទី១៖ រឿងសូផាត (រីម គីន)៖ សូផាត ជាក្មេងដែលជួបការលំបាកតាំងពីតូច តែមិនបោះបង់ទេ។ គាត់តស៊ូរៀនសូត្រ ទ្រាំទ្រការលំបាក រហូតមានចំណេះ និងជីវិតល្អប្រសើរ។ ការតស៊ូ និងការសិក្សាបានផ្លាស់ប្តូរវាសនារបស់គាត់។ ចំណេះរបស់គាត់កើតពីការរៀនបន្តិចម្តងៗ រាល់ថ្ងៃ។"},{"content":"ឧទាហរណ៍ទី២៖ រឿងកុលាបប៉ៃលិន (ញ៉ុក ថែម)៖ ចៅចិត្ត ជាយុវជនក្រីក្រ ខិតខំធ្វើការដោយស្មោះត្រង់ និងរៀនចេះលេខ ចេះភាសា។ លោកហ្លួងរតនសម្បត្តិ ឃើញពីសមត្ថភាព និងចរិតល្អរបស់គាត់ ក៏ទុកចិត្ត ហើយលើកកូនស្រីឲ្យរៀបការជាមួយ។ ការងារ និងការព្យាយាមបាននាំឲ្យចៅចិត្តមានជីវិតសុខសប្បាយ។ គាត់ធ្វើការបន្តិចម្តងៗ សន្សំចំណេះ និងទំនុកចិត្ត រហូតបានជីវិតល្អ។"},{"content":"ឧទាហរណ៍ទី៣៖ រឿងរាមកេរ្តិ៍៖ ព្រះរាមរៀនវិជ្ជាពីឥសី ហើយព្រមចេញទៅនៅព្រៃ ដើម្បីរក្សាពាក្យសច្ចៈរបស់ព្រះបិតា។ ពេលនាងសីតាត្រូវក្រុងរាពណ៍ចាប់ ព្រះអង្គមិនបោះបង់ទេ តែតស៊ូ ប្រមូលកម្លាំង និងរកដំណោះស្រាយ រហូតជួយនាងបានវិញ។ ជ័យជម្នះកើតពីការប្រមូលកម្លាំង និងការសាងស្ពានម្តងមួយដុំៗ។"},{"content":"សរុបមតិ៖ តាមឧទាហរណ៍ខាងលើ ការខិតខំបន្តិចម្តងៗដោយជាប់លាប់ ពិតជានាំមកនូវលទ្ធផលធំមែន។"},{"content":"សេចក្តីបញ្ចប់៖ សុភាសិតនេះមានតម្លៃអប់រំ ជាពិសេសសម្រាប់សិស្ស។ យើងត្រូវរៀនរាល់ថ្ងៃ សន្សំចំណេះ និងសន្សំប្រាក់បន្តិចៗ ដើម្បីអនាគតដ៏ល្អ។"},{"content":"ចំណាំ៖ នេះជាអត្ថបទគំរូមួយក្នុងចំណោមចម្លើយល្អៗជាច្រើន។ សិស្សអាចលើករឿងផ្សេងទៀតដែលបានរៀន ឲ្យតែត្រូវនឹងប្រធាន ហើយគួរផ្ទៀងផ្ទាត់ឈ្មោះតួអង្គ និងអ្នកនិពន្ធជាមួយសៀវភៅសិក្សា។"}]'::jsonb, 'ai-generated', 'Answer key written by AI (Claude) for Meh Rean from the typed question; not checked by a teacher.', 'needs-review')
on conflict (question_id) do update set answer = excluded.answer, steps = excluded.steps, source = excluded.source
  where public.question_solutions.origin = 'ai-generated' and public.question_solutions.verification <> 'verified';

insert into public.exam_papers (id, subject_id, year, title_en, title_km, duration_minutes, duration_source, origin, source, verification)
values ('bacc2020-2014-4100-8000-000000000000', 'kh-grade12-social-khmer-literature', 2014, 'BacII 2014, first sitting: Khmer literature (social science track)', 'វិញ្ញាសាអក្សរសាស្ត្រខ្មែរ បាក់ឌុបឆ្នាំ២០១៤ លើកទី១ (ថ្នាក់វិទ្យាសាស្ត្រសង្គម)', 150, 'Printed on the paper: រយៈពេល ១៥០ នាទី', 'official', 'BacII 2014, first sitting (2014-08-04), social science track khmer literature, Ministry of Education, Youth and Sport. Typed by Meh Rean from one copy: retyped by ជៀប គន្ធា (github.com/HELMAB/bacii). Not yet checked against the Ministry''s original.', 'needs-review')
on conflict (id) do update set title_en = excluded.title_en, title_km = excluded.title_km, duration_minutes = excluded.duration_minutes,
  duration_source = excluded.duration_source, source = excluded.source;

